from atexit import register
from typing import Any
from weakref import WeakValueDictionary
import json
import uuid
from base64 import b64encode

import requests

from taf.gnb.oam.coam.cu.utilities.logger import log_sending_message, log_received_response
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage

from taf.gnb.oam.coam.cu.exception import ApiException


class SECLicensedv1:
    """ This class provides a client for the SEC-LICENSED v1 API """
    _instances: Any = WeakValueDictionary()

    def __new__(cls, con_details=None, *args, **kwargs):
        connection_name = con_details.alias

        if connection_name not in cls._instances:
            instance = super().__new__(cls)
            cls._instances[connection_name] = instance

        return cls._instances[connection_name]

    def __init__(self, con_details=None):
        if not hasattr(self, "_initialized"):
            self._initialized = True
            self.con_details = con_details
            self.url = con_details.make_configuration_host(
                original_endpoint="http://localhost/api/licensed/sec/v1")
            self.token_storage = TokenStorage(connection_name=con_details.alias)

    def login(self, username, password, timeout=None):
        headers = {
            "Authorization": f"Basic {self._get_basic_access_token(username=username, password=password)}",
            "Content-Type": "application/json",
            "accept": "application/json"
        }
        endpoint = self.url + "/login"
        request_id = uuid.uuid4()

        log_sending_message(request_id=request_id,
                            endpoint=endpoint,
                            headers=headers,
                            method="POST",
                            connection_alias=self.con_details.alias)

        try:
            response = requests.post(url=endpoint,
                                     headers=headers,
                                     data=json.dumps({"ReadOnlyMode": self.con_details.read_only}),
                                     verify=False,
                                     timeout=timeout)

            log_received_response(request_id=request_id,
                                  response=response,
                                  endpoint=endpoint,
                                  method="POST",
                                  connection_alias=self.con_details.alias)

            response.raise_for_status()

        except requests.exceptions.HTTPError as e:
            if e.response.status_code == 403:
                raise Exception("Login using M2M failed. Please make sure M2M interface is enabled (actCli parameter on"
                                "vCU needs to be set to True). If this is your first login after deployment, please use "
                                "'perform_commissioning' keyword to commission")
            else:
                raise ApiException(http_response=e.response)

        self.token_storage.access_token = response.json()['Token']
        self.token_storage.expires_at = response.json()['Expires']

        return response.json()

    def logout(self, timeout=None):
        request_id = uuid.uuid4()
        endpoint = self.url + "/logout"
        headers = {
            "Authorization": f"Bearer {self.token_storage.access_token}",
            "accept": "*/*"
        }

        log_sending_message(request_id=request_id,
                            endpoint=endpoint,
                            headers=headers,
                            method="POST",
                            connection_alias=self.con_details.alias)

        response = requests.post(url=endpoint,
                      headers=headers,
                      verify=False,
                      timeout=timeout)

        log_received_response(request_id=request_id,
                              response=response,
                              endpoint=endpoint,
                              method="POST",
                              connection_alias=self.con_details.alias)

    @classmethod
    def get_instance(cls, connection_name):
        """Returns instance for connection with given connection_name"""
        return cls._instances[connection_name]

    @classmethod
    def remove_instance(cls, connection_name):
        """Remove instance of SECLicensedv1 and TokenStorage for given connection_name"""
        if connection_name in cls._instances:
            cls._instances[connection_name].token_storage.remove_instance(connection_name=connection_name)
            del cls._instances[connection_name]

    @classmethod
    def clear_instances(cls):
        """Removes all existing instances of SECLicensedv1 and TokenStorage"""
        for connection_name, instance in cls._instances.items():
            instance.token_storage.remove_instance(connection_name)
        cls._instances.clear()

    @staticmethod
    def _get_basic_access_token(username="Nemuadmin", password="Nokia@123"):
        basic_auth_token = f"{username}:{password}"
        return b64encode(basic_auth_token.encode(encoding='utf-8')).decode()

register(SECLicensedv1.clear_instances)
